// Verse-free kernel of how Huge Things turns many plants' desired footprints into real blocker cells safely (GPT review
// 2026-10-07, #1 #2 #5 #6 #8 #9 #16; owner ruling 2026-10-07 20:38 on #4). SelfTest/HugeThingsFuzz.cs compiles this file:
// no Verse/RimWorld/UnityEngine. Cells are RM_HugeFootprintKernel.Key(x, z) longs.
//   ClaimLedger      multi-owner cell claims: a cell is blocked while ANY owner claims it; one physical blocker per cell;
//                    the result never depends on the order owners registered or refreshed in.
//   Planner          which claimed-but-open cells may close NOW: never a cell holding a pawn or an item (so nothing is ever
//                    moved aside or destroyed), never a protected cell (buildings, blueprints, frames, their interaction cells,
//                    door approaches, trees, other giants, unwalkable ground), and never one whose closing would cut a
//                    passable component apart anywhere on the map (including pawn clearance) or cut a giant's root off
//                    from every open 4-neighbour (it must stay cuttable). A refused cell is deferred, not dropped.
//   FootprintSignature  everything the geometry depends on, compared field by field (the selection/refresh cache key).
//   DamageDedup      one forwarded hit per (tick, source, owner): a beam or blast crossing several cells of one giant hits it once.
using System;
using System.Collections.Generic;

namespace RimMandrake.HugeThings
{
    /// <summary>Logical work units, not elapsed time. Callers charge visits and reserve bulk copies/sorts BEFORE doing
    /// them. Exhaustion is caught only at a read/transaction boundary; no unproved blocker is spawned. Oversized read
    /// jobs remain deferred (safe open cells), rather than bypassing the cap. Runtime latency is UNVERIFIED.</summary>
    public sealed class FootprintWorkBudget
    {
        public readonly int Limit;
        public int Used { get; private set; }
        public int Refusals { get; private set; }
        private readonly FootprintWorkBudget parent;
        public FootprintWorkBudget(int limit, FootprintWorkBudget parent = null) { this.parent = parent; if (limit < 0) throw new ArgumentOutOfRangeException(nameof(limit)); Limit = limit; }
        public void Spend(long units = 1)
        {
            if (units < 0) throw new ArgumentOutOfRangeException(nameof(units));
            if (units > Limit - Used) { Refusals++; throw new FootprintBudgetExhausted(); }
            parent?.Spend(units);
            Used += (int)units;
        }
    }

    public sealed class FootprintBudgetExhausted : Exception { }

    /// <summary>FIFO with deduplicated owners; requeue AFTER a visit. No phase can monopolize a tick.</summary>
    public sealed class FootprintOwnerQueue
    {
        private readonly Queue<int> queue = new Queue<int>();
        private readonly HashSet<int> queued = new HashSet<int>();
        public int Count => queue.Count;
        public void Add(int id) { if (queued.Add(id)) queue.Enqueue(id); }
        public bool Next(out int id)
        {
            if (queue.Count == 0) { id = -1; return false; }
            id = queue.Dequeue(); queued.Remove(id); return true;
        }
    }

    public sealed class ClaimLedger
    {
        private readonly Dictionary<long, SortedSet<int>> cellOwners = new Dictionary<long, SortedSet<int>>();
        private readonly Dictionary<int, SortedSet<long>> ownerCells = new Dictionary<int, SortedSet<long>>();

        public bool IsClaimed(long cell) => cellOwners.ContainsKey(cell);

        public int ClaimedCount => cellOwners.Count;

        /// <summary>The owner a cell answers to (labels, damage): the lowest id among its claimants, or -1.</summary>
        public int PrimaryOwner(long cell) => cellOwners.TryGetValue(cell, out SortedSet<int> o) && o.Count > 0 ? o.Min : -1;

        public IEnumerable<long> Claimed => cellOwners.Keys;

        /// <summary>Every owner claiming a cell (ascending), or none.</summary>
        public IEnumerable<int> OwnersOf(long cell)
        {
            if (cellOwners.TryGetValue(cell, out SortedSet<int> o)) return o;
            return Array.Empty<int>();
        }

        public IEnumerable<long> CellsOf(int owner)
        {
            if (ownerCells.TryGetValue(owner, out SortedSet<long> c)) return c;
            return Array.Empty<long>();
        }

        /// <summary>Replace an owner's claims. becameClaimed: cells nobody claimed before; becameFree: cells nobody claims now.</summary>
        public void Set(int owner, IEnumerable<long> cells, List<long> becameClaimed, List<long> becameFree)
        {
            HashSet<long> want = new HashSet<long>(cells);
            if (!ownerCells.TryGetValue(owner, out SortedSet<long> had))
            {
                had = new SortedSet<long>();
                ownerCells[owner] = had;
            }
            List<long> drop = new List<long>();
            foreach (long c in had) if (!want.Contains(c)) drop.Add(c);
            drop.Sort();
            foreach (long c in drop)
            {
                had.Remove(c);
                SortedSet<int> o = cellOwners[c];
                o.Remove(owner);
                if (o.Count == 0)
                {
                    cellOwners.Remove(c);
                    becameFree?.Add(c);
                }
            }
            List<long> add = new List<long>();
            foreach (long c in want) if (!had.Contains(c)) add.Add(c);
            add.Sort();
            foreach (long c in add)
            {
                had.Add(c);
                if (!cellOwners.TryGetValue(c, out SortedSet<int> o))
                {
                    o = new SortedSet<int>();
                    cellOwners[c] = o;
                    becameClaimed?.Add(c);
                }
                o.Add(owner);
            }
            if (had.Count == 0) ownerCells.Remove(owner);
        }

        public bool AddCell(int owner, long cell)
        {
            if (!ownerCells.TryGetValue(owner, out SortedSet<long> cells)) ownerCells[owner] = cells = new SortedSet<long>();
            cells.Add(cell);
            bool fresh = !cellOwners.TryGetValue(cell, out SortedSet<int> owners);
            if (fresh) cellOwners[cell] = owners = new SortedSet<int>();
            owners.Add(owner); return fresh;
        }

        public bool ReleaseCell(int owner, long cell)
        {
            if (!ownerCells.TryGetValue(owner, out SortedSet<long> cells) || !cells.Remove(cell)) return false;
            if (cells.Count == 0) ownerCells.Remove(owner);
            SortedSet<int> owners = cellOwners[cell]; owners.Remove(owner);
            if (owners.Count > 0) return false;
            cellOwners.Remove(cell); return true;
        }

        public int CountOf(int owner) => ownerCells.TryGetValue(owner, out SortedSet<long> cells) ? cells.Count : 0;

        /// <summary>One affected claim, for budgeted mass removal; never walks remaining blockers.</summary>
        public bool RemoveNext(int owner, out long cell, out bool freed)
        {
            cell = 0; freed = false;
            if (!ownerCells.TryGetValue(owner, out SortedSet<long> cells) || cells.Count == 0) return false;
            cell = cells.Min; cells.Remove(cell);
            if (cells.Count == 0) ownerCells.Remove(owner);
            SortedSet<int> owners = cellOwners[cell]; owners.Remove(owner);
            if (owners.Count == 0) { cellOwners.Remove(cell); freed = true; }
            return true;
        }

        public void Remove(int owner, List<long> becameFree) => Set(owner, Array.Empty<long>(), null, becameFree);
    }

    [Flags]
    public enum CellFlags
    {
        None = 0,
        Passable = 1,     // a pawn can walk here now (vanilla Walkable, which is false under any impassable edifice)
        Pawn = 2,
        Item = 4,
        Protected = 8,    // building/blueprint/frame/interaction cell/door approach/tree/other giant/indestructible/bad ground
    }

    public static class Planner
    {
        public const int Margin = 4;

        /// <summary>Bounds a local reconnection proof by the supplied cells/root plus Margin. Runtime retries use a
        /// single candidate; batch callers can supply a fixed whole-footprint window for fixpoint idempotence. The
        /// global safety proof never treats this window's border as a map exit: ambiguous closures stay open.</summary>
        public static CellBox Window(IEnumerable<long> footprint, long root)
        {
            int minX = RM_HugeFootprintKernel.KeyX(root), minZ = RM_HugeFootprintKernel.KeyZ(root), maxX = minX, maxZ = minZ;
            foreach (long k in footprint)
            {
                int x = RM_HugeFootprintKernel.KeyX(k), z = RM_HugeFootprintKernel.KeyZ(k);
                if (x < minX) minX = x;
                if (z < minZ) minZ = z;
                if (x > maxX) maxX = x;
                if (z > maxZ) maxZ = z;
            }
            return new CellBox(minX - Margin, minZ - Margin, maxX + Margin, maxZ + Margin);
        }

        /// <summary>
        /// Decide which of `wanted` (claimed, not yet blocked) may close now, in a deterministic order. flagsAt answers for
        /// any cell; roots keep an open neighbour. Local reconnection is a sufficient proof of GLOBAL connectivity:
        /// every surviving neighbour of the deleted anchor set must reconnect without leaving the window. Every global
        /// path through deleted anchors can then substitute that local path. Ambiguous closures stay open. Clearance
        /// boxes specify occupied width/height (their position is irrelevant); 1x1 is always checked too.
        /// </summary>
        public static List<long> Plan(IList<long> wanted, IList<long> roots, Func<long, CellFlags> flagsAt, CellBox window, IList<CellBox> clearance = null, FootprintWorkBudget budget = null)
        {
            List<long> accepted = new List<long>();
            if (wanted == null || wanted.Count == 0) return accepted;
            int minX = window.MinX, minZ = window.MinZ, maxX = window.MaxX, maxZ = window.MaxZ;
            long lw = (long)maxX - minX + 1, lh = (long)maxZ - minZ + 1;
            if (lw <= 0 || lh <= 0 || lw * lh > MaxWindowCells) return accepted;   // A3.12: refuse an unbounded window
            int w = (int)lw, h = (int)lh;
            budget?.Spend(w * (long)h);
            bool[] pass = new bool[w * h];
            for (int z = 0; z < h; z++)
                for (int x = 0; x < w; x++)
                {
                    budget?.Spend();
                    pass[z * w + x] = (flagsAt(RM_HugeFootprintKernel.Key(minX + x, minZ + z)) & CellFlags.Passable) != 0;
                }

            bool[] before = Reach(pass, w, h, budget);
            List<int> rootIdx = new List<int>();
            if (roots != null)
            {
                foreach (long k in roots)
                {
                    budget?.Spend();
                    if (!window.Contains(RM_HugeFootprintKernel.KeyX(k), RM_HugeFootprintKernel.KeyZ(k))) continue;
                    int i = (RM_HugeFootprintKernel.KeyZ(k) - minZ) * w + (RM_HugeFootprintKernel.KeyX(k) - minX);
                    if (RootServed(i, pass, pass, w, h)) rootIdx.Add(i);   // only roots that have access now must keep it
                }
            }

            // Reserve copies, hashing and comparison-sort work before allocating them.
            budget?.Spend(8L * wanted.Count * (1 + (long)Math.Ceiling(Math.Log(wanted.Count + 1, 2))));
            List<long> order = new List<long>(new HashSet<long>(wanted));
            order.Sort((a, b) =>
            {
                int za = RM_HugeFootprintKernel.KeyZ(a), zb = RM_HugeFootprintKernel.KeyZ(b);
                if (za != zb) return za.CompareTo(zb);
                return RM_HugeFootprintKernel.KeyX(a).CompareTo(RM_HugeFootprintKernel.KeyX(b));
            });
            // Repeat to a fixpoint: a cell refused because closing it would cut off a neighbour becomes acceptable once that
            // neighbour itself closes later in the pass (measured: without this a second pass closed more, 132/3000 cases).
            bool progress = true;
            while (progress)
            {
                progress = false;
                for (int n = 0; n < order.Count; n++)
                {
                    budget?.Spend();
                    long k = order[n];
                    CellFlags f = flagsAt(k);
                    if (!window.Contains(RM_HugeFootprintKernel.KeyX(k), RM_HugeFootprintKernel.KeyZ(k))) continue;
                    if ((f & CellFlags.Passable) == 0 || (f & (CellFlags.Pawn | CellFlags.Item | CellFlags.Protected)) != 0) continue;
                    int i = (RM_HugeFootprintKernel.KeyZ(k) - minZ) * w + (RM_HugeFootprintKernel.KeyX(k) - minX);
                    budget?.Spend(rootIdx.Count);
                    if (rootIdx.Contains(i) || !pass[i]) continue;
                    pass[i] = false;
                    bool[] after = Reach(pass, w, h, budget);
                    bool ok = Reconnects(i, pass, w, h, 1, 1, budget);
                    if (clearance != null)
                        foreach (CellBox size in clearance)
                        {
                            budget?.Spend();
                            if (!ok) break;
                            ok = Reconnects(i, pass, w, h, size.MaxX - size.MinX + 1, size.MaxZ - size.MinZ + 1, budget);
                        }
                    for (int j = 0; j < pass.Length && ok; j++)
                    {
                        budget?.Spend();
                        if (pass[j] && before[j] && !after[j]) ok = false;     // a cell that reached the border no longer does
                    }
                    for (int r = 0; r < rootIdx.Count && ok; r++)
                    {
                        budget?.Spend();
                        if (!RootServed(rootIdx[r], pass, pass, w, h)) ok = false;
                    }
                    if (ok)
                    {
                        accepted.Add(k);
                        before = after;
                        progress = true;
                    }
                    else
                    {
                        pass[i] = true;
                    }
                }
            }
            // PLANT_FOOTPRINT_HARDENING_1 (A3.3): returned in ACCEPTANCE order, never re-sorted. A cell accepted on a later fixpoint
            // round depends on cells accepted before it; every prefix of this list is safe to close on its own, so a realizer
            // must spawn in this order and stop at its first failure (RealizeInOrder).
            return accepted;
        }

        // pass already has the candidate closed. In the anchor graph, closing a physical cell deletes all
        // previously valid occupied rectangles containing it. Require ALL surviving neighbours of that set to
        // reconnect locally. This is conservative even when the deleted anchors had separate components before.
        private static bool Reconnects(int cell, bool[] pass, int w, int h, int sx, int sz, FootprintWorkBudget budget)
        {
            int cx = cell % w, cz = cell / w;
            if (sx <= 0 || sz <= 0 || cx - sx < 0 || cz - sz < 0 || cx + sx >= w || cz + sz >= h) return false;
            bool Fits(int x, int z, bool before)
            {
                budget?.Spend();
                if (x < 0 || z < 0 || x + sx > w || z + sz > h) return false;
                for (int dz = 0; dz < sz; dz++)
                    for (int dx = 0; dx < sx; dx++)
                    {
                        budget?.Spend();
                        int i = (z + dz) * w + x + dx;
                        if (!pass[i] && !(before && i == cell)) return false;
                    }
                return true;
            }
            var boundary = new HashSet<int>();
            int[] dxs = { 1, -1, 0, 0, 1, 1, -1, -1 }, dzs = { 0, 0, 1, -1, 1, -1, 1, -1 };
            for (int z = cz - sz + 1; z <= cz; z++)
                for (int x = cx - sx + 1; x <= cx; x++)
                {
                    if (!Fits(x, z, true)) continue;
                    // Include diagonal boundary edges too; reconnect via cardinal steps, a sufficient proof for both.
                    for (int d = 0; d < 8; d++)
                    {
                        int nx = x + dxs[d], nz = z + dzs[d];
                        if (Fits(nx, nz, false)) boundary.Add(nz * w + nx);
                    }
                }
            if (boundary.Count <= 1) return true;
            var seen = new HashSet<int>();
            var todo = new Stack<int>();
            foreach (int i in boundary) { todo.Push(i); seen.Add(i); break; }
            while (todo.Count > 0)
            {
                budget?.Spend();
                int i = todo.Pop();
                boundary.Remove(i);
                if (boundary.Count == 0) return true;
                for (int d = 0; d < 4; d++)
                {
                    int x = i % w + dxs[d], z = i / w + dzs[d];
                    int next = z * w + x;
                    if (Fits(x, z, false) && seen.Add(next)) todo.Push(next);
                }
            }
            return false;
        }

        /// <summary>PLANT_FOOTPRINT_HARDENING_1 (A3.3): realize `accepted` in order and stop at the first cell that fails, leaving it and
        /// everything after it pending (a later cell may depend on it). Returns how many were realized.</summary>
        public static int RealizeInOrder(IList<long> accepted, Func<long, bool> realize)
        {
            int n = 0;
            for (int i = 0; i < accepted.Count; i++)
            {
                if (!realize(accepted[i])) break;
                n++;
            }
            return n;
        }

        /// <summary>PLANT_FOOTPRINT_HARDENING_1 (A3.12): the largest window Plan will allocate for; a bigger one (bad def data) plans
        /// nothing rather than allocating w*h unbounded.</summary>
        public const long MaxWindowCells = 512L * 512L;

        private static bool RootServed(int i, bool[] pass, bool[] reach, int w, int h)
        {
            int x = i % w, z = i / w;
            int[] dx = { 1, -1, 0, 0 }, dz = { 0, 0, 1, -1 };
            for (int d = 0; d < 4; d++)
            {
                int nx = x + dx[d], nz = z + dz[d];
                if (nx < 0 || nz < 0 || nx >= w || nz >= h) return true;   // touches the border: reachable from outside
                int j = nz * w + nx;
                if (pass[j] && reach[j]) return true;
            }
            return false;
        }

        /// <summary>4-connected flood from every passable border cell.</summary>
        public static bool[] Reach(bool[] pass, int w, int h, FootprintWorkBudget budget = null)
        {
            budget?.Spend(pass.Length); // allocation/zeroing
            bool[] seen = new bool[pass.Length];
            Stack<int> st = new Stack<int>();
            for (int x = 0; x < w; x++)
            {
                budget?.Spend();
                Seed(x, pass, seen, st);
                Seed((h - 1) * w + x, pass, seen, st);
            }
            for (int z = 0; z < h; z++)
            {
                budget?.Spend();
                Seed(z * w, pass, seen, st);
                Seed(z * w + w - 1, pass, seen, st);
            }
            while (st.Count > 0)
            {
                budget?.Spend();
                int i = st.Pop();
                int x = i % w, z = i / w;
                if (x > 0) Seed(i - 1, pass, seen, st);
                if (x < w - 1) Seed(i + 1, pass, seen, st);
                if (z > 0) Seed(i - w, pass, seen, st);
                if (z < h - 1) Seed(i + w, pass, seen, st);
            }
            return seen;
        }

        private static void Seed(int i, bool[] pass, bool[] seen, Stack<int> st)
        {
            if (pass[i] && !seen[i])
            {
                seen[i] = true;
                st.Push(i);
            }
        }
    }

    /// <summary>
    /// Owner ruling 2026-10-07 21:08 (decision taken by question card): a footprint cell held only by items closes after its
    /// items are pushed, gently, to the nearest free valid cell that is in NO footprint (claimed by any plant); pawns are
    /// never moved. Every item of a cell must fit or none moves (the cell then stays open). Capacity is shared across the
    /// whole pass so two cells never overfill one destination. Search is a 4-connected BFS over cells with capacity >= 0
    /// (passable ground), preferred cells first at each distance, then key order: deterministic.
    /// </summary>
    public static class ItemMover
    {
        public const int MaxRadius = 12;

        /// <summary>
        /// For each source cell (in key order) with itemCounts[cell] items, a destination per item, or no entry when they
        /// do not all fit. capacity(k): how many more items cell k takes (-1 = not a valid cell at all). excluded(k): in some
        /// footprint. preferred(src, k): e.g. the same stockpile as the source.
        /// </summary>
        public static Dictionary<long, List<long>> Assign(IDictionary<long, int> itemCounts, Func<long, int> capacity,
                                                          Func<long, bool> excluded, Func<long, long, bool> preferred, FootprintWorkBudget budget = null)
        {
            Dictionary<long, List<long>> outMoves = new Dictionary<long, List<long>>();
            Dictionary<long, int> used = new Dictionary<long, int>();
            budget?.Spend(8L * itemCounts.Count * (1 + (long)Math.Ceiling(Math.Log(itemCounts.Count + 1, 2))));
            List<long> srcs = new List<long>(itemCounts.Keys);
            srcs.Sort();
            foreach (long src in srcs)
            {
                int need = itemCounts[src];
                if (need <= 0) continue;
                List<long> dests = new List<long>();
                Dictionary<long, int> take = new Dictionary<long, int>();
                foreach (long k in Ring(src, capacity, preferred, budget))
                {
                    if (k == src || excluded(k)) continue;
                    int cap = capacity(k) - (used.TryGetValue(k, out int u) ? u : 0) - (take.TryGetValue(k, out int t) ? t : 0);
                    while (cap > 0 && dests.Count < need)
                    {
                        budget?.Spend();
                        dests.Add(k);
                        take[k] = (take.TryGetValue(k, out int t2) ? t2 : 0) + 1;
                        cap--;
                    }
                    if (dests.Count == need) break;
                }
                if (dests.Count < need) continue;
                foreach (KeyValuePair<long, int> kv in take) used[kv.Key] = (used.TryGetValue(kv.Key, out int u2) ? u2 : 0) + kv.Value;
                outMoves[src] = dests;
            }
            return outMoves;
        }

        /// <summary>
        /// PLANT_FOOTPRINT_HARDENING_1 (C3.2): Assign reserves destinations BEFORE the planner runs, so a source the planner then
        /// refuses kept its reservation and could starve another source forever. Assign and plan are iterated: a refused source
        /// is dropped and the rest re-assigned, until every source holding a reservation is one the planner accepts. plan(moves)
        /// returns the accepted cells for that move set. Terminates: each round removes at least one source.
        /// </summary>
        public static Dictionary<long, List<long>> AssignAndPlan(IDictionary<long, int> itemCounts, Func<long, int> capacity,
                                                                 Func<long, bool> excluded, Func<long, long, bool> preferred,
                                                                 Func<Dictionary<long, List<long>>, List<long>> plan,
                                                                 out List<long> accepted, FootprintWorkBudget budget = null)
        {
            budget?.Spend(itemCounts.Count);
            var counts = new Dictionary<long, int>(itemCounts);
            while (true)
            {
                Dictionary<long, List<long>> moves = Assign(counts, capacity, excluded, preferred, budget);
                accepted = plan(moves);
                var ok = new HashSet<long>(accepted);
                var refused = new List<long>();
                foreach (long src in moves.Keys) if (!ok.Contains(src)) refused.Add(src);
                if (refused.Count == 0) return moves;
                foreach (long src in refused) counts.Remove(src);
            }
        }

        /// <summary>Cells reachable from src over capacity >= 0 ground, nearest first (BFS layers), preferred first within a
        /// layer, then by key.</summary>
        private static IEnumerable<long> Ring(long src, Func<long, int> capacity, Func<long, long, bool> preferred, FootprintWorkBudget budget)
        {
            HashSet<long> seen = new HashSet<long> { src };
            List<long> layer = new List<long> { src };
            for (int d = 0; d < MaxRadius && layer.Count > 0; d++)
            {
                List<long> next = new List<long>();
                foreach (long k in layer)
                {
                    budget?.Spend();
                    int x = RM_HugeFootprintKernel.KeyX(k), z = RM_HugeFootprintKernel.KeyZ(k);
                    long[] ns = { RM_HugeFootprintKernel.Key(x + 1, z), RM_HugeFootprintKernel.Key(x - 1, z),
                                  RM_HugeFootprintKernel.Key(x, z + 1), RM_HugeFootprintKernel.Key(x, z - 1) };
                    foreach (long n in ns)
                    {
                        budget?.Spend();
                        if (seen.Add(n) && capacity(n) >= 0) next.Add(n);
                    }
                }
                budget?.Spend(8L * next.Count * (1 + (long)Math.Ceiling(Math.Log(next.Count + 1, 2))));
                next.Sort((a, b) =>
                {
                    bool pa = preferred != null && preferred(src, a), pb = preferred != null && preferred(src, b);
                    if (pa != pb) return pa ? -1 : 1;
                    return a.CompareTo(b);
                });
                foreach (long k in next) yield return k;
                layer = next;
            }
        }
    }

    public static class RootRule
    {
        /// <summary>Owner ruling 2026-10-07 21:08: a huge plant whose every measured picture touches the ground only in its
        /// own cell makes that cell impassable (the plant itself), so it is still solid somewhere. Generic, never per species.
        /// </summary>
        public static bool RootImpassable(bool blockingEnabled, bool blockingSupported, IList<int> contactCountsPerVariant)
        {
            if (!blockingEnabled || !blockingSupported || contactCountsPerVariant == null || contactCountsPerVariant.Count == 0) return false;
            for (int i = 0; i < contactCountsPerVariant.Count; i++) if (contactCountsPerVariant[i] != 0) return false;
            return true;
        }
    }

    /// <summary>Everything a plant's footprint depends on. Two equal signatures give equal footprints and selection rects.</summary>
    public struct FootprintSignature : IEquatable<FootprintSignature>
    {
        public int RootX, RootZ, MaskId;
        public float DrawX, Visual, JitterX, JitterZ, BlockScale;
        public bool Flip, Measured, Blocking, Selecting, OldEnough;

        public bool Equals(FootprintSignature o)
            => RootX == o.RootX && RootZ == o.RootZ && MaskId == o.MaskId && DrawX == o.DrawX && Visual == o.Visual
            && JitterX == o.JitterX && JitterZ == o.JitterZ && BlockScale == o.BlockScale && Flip == o.Flip
            && Measured == o.Measured && Blocking == o.Blocking && Selecting == o.Selecting && OldEnough == o.OldEnough;

        public override bool Equals(object obj) => obj is FootprintSignature o && Equals(o);

        public override int GetHashCode()
        {
            unchecked
            {
                int h = RootX * 73856093 ^ RootZ * 19349663 ^ MaskId * 83492791;
                h = h * 31 + Visual.GetHashCode();
                h = h * 31 + BlockScale.GetHashCode();
                return h * 31 + (Flip ? 1 : 0) + (Blocking ? 2 : 0) + (Selecting ? 4 : 0) + (OldEnough ? 8 : 0) + (Measured ? 16 : 0);
            }
        }
    }

    /// <summary>One-entry cache keyed on a full signature.</summary>
    public sealed class SignatureCache<T>
    {
        private bool has;
        private FootprintSignature key;
        private T value;

        public T Get(FootprintSignature sig, Func<FootprintSignature, T> compute)
        {
            if (has && key.Equals(sig)) return value;
            value = compute(sig);
            key = sig;
            has = true;
            return value;
        }

        public void Clear() => has = false;
    }

    /// <summary>One forwarded hit per (tick, source, owner).</summary>
    public sealed class DamageDedup
    {
        private int tick = int.MinValue;
        private readonly HashSet<(long, int)> seen = new HashSet<(long, int)>();

        /// <summary>PLANT_INTERACTION_GUARDS_1 (A3.7): only an AREA event (an explosion, a multi-cell titan step) is deduplicated per
        /// (tick, source, owner). A single projectile is its own event: 1.6 Bullet.Impact makes one DamageInfo per projectile, so
        /// pellets or burst rounds from one launcher in one tick each land.</summary>
        public bool ShouldForward(int nowTick, long sourceKey, int ownerId, bool areaEvent)
        {
            if (!areaEvent) return true;
            return ShouldForward(nowTick, sourceKey, ownerId);
        }

        public bool ShouldForward(int nowTick, long sourceKey, int ownerId)
        {
            if (nowTick != tick)
            {
                tick = nowTick;
                seen.Clear();
            }
            return seen.Add((sourceKey, ownerId));
        }
    }

    /// <summary>PLANT_INTERACTION_GUARDS_1 (C3.3): the drawn size a huge pawn's hitbox is built from. 1.6
    /// PawnRenderNode_AnimalPart.GraphicFor draws an alternate graphic or femaleGraphicData when one applies, and the mesh follows
    /// THAT graphic's drawSize; the hitbox takes the larger of it and the body graphic per axis, so it never shrinks below the
    /// default body.</summary>
    public static class HitboxDraw
    {
        public static void Pick(float bodyX, float bodyY, bool hasActive, float activeX, float activeY, out float x, out float y)
        {
            x = bodyX; y = bodyY;
            if (!hasActive) return;
            if (!float.IsNaN(activeX) && activeX > x) x = activeX;
            if (!float.IsNaN(activeY) && activeY > y) y = activeY;
        }
    }
}

using RimWorld;
using Verse;

namespace RimMandrake.HugeThings
{
    /// <summary>
    /// One invisible solid cell of a huge plant's ground footprint. It reads as the plant (label, mouseover), can't be
    /// deconstructed or claimed, and is owned by MapComponent_HugeFootprints, which spawns and removes it.
    ///
    /// Cover and damage (owner ruling, decision taken by question card 2026-10-07 20:38 PDT): a trunk cell gives partial
    /// cover, and a shot that hits it damages the giant plant itself, once per projectile / beam / blast. Verified against
    /// decompiled 1.6: Projectile.CheckForFreeIntercept lets a non-pawn thing with fillPercent > 0.2 stop a shot (CanHit
    /// needs NonTargetWorld, not isTargetable); Projectile.Impact -> Thing.TakeDamage -> PreApplyDamage, where this cell
    /// absorbs the hit and forwards it to its owner. Explosions are rerouted earlier (HugeThingsCore's
    /// ExplosionDamageThing prefix) using the explosion's own damagedThings list, so a blast covering ten trunk cells and
    /// the root hits the plant once.
    /// </summary>
    public class Building_TrunkBlocker : Building
    {
        /// <summary>The claimant this cell answers to (lowest thing id among the plants claiming it). Set by the map
        /// component; saved only for labels before the first reconcile.</summary>
        public Plant owner;

        private static readonly DamageDedup Dedup = new DamageDedup();

        public override string LabelNoCount => owner != null ? owner.LabelNoCount : base.LabelNoCount;

        public override void ExposeData()
        {
            base.ExposeData();
            Scribe_References.Look(ref owner, "owner");
        }

        public override AcceptanceReport DeconstructibleBy(Faction faction) => false;

        public override AcceptanceReport ClaimableBy(Faction by) => false;

        public override void PreApplyDamage(ref DamageInfo dinfo, out bool absorbed)
        {
            absorbed = true;   // the cell itself never takes damage (it has no hit points to take it with)
            if (!RM_HugeThingsSettings.PlantTrunkDamageActive) return;   // Mod Settings: cover only, the plant is unharmed
            // PLANT_INTERACTION_GUARDS_1 (A3.7): a hit reaching a trunk cell here is a single projectile, beam cell or melee blow
            // (explosions are rerouted before this by the ExplosionDamageThing prefix), so it is forwarded un-deduplicated.
            ForwardToPlant(owner, dinfo, false);
        }

        /// <summary>The one damage route into a giant plant from its trunk or from a titan smashing it. An AREA event (one titan
        /// step brushing several trunk cells) lands once per (tick, source, plant); a single projectile always lands
        /// (PLANT_INTERACTION_GUARDS_1, A3.7). True if it was dealt.</summary>
        public static bool ForwardToPlant(Plant p, DamageInfo dinfo, bool areaEvent)
        {
            if (p == null || p.Destroyed || !p.Spawned || dinfo.Amount <= 0f) return false;
            if (!Dedup.ShouldForward(Find.TickManager.TicksGame, SourceKey(dinfo), p.thingIDNumber, areaEvent)) return false;
            p.TakeDamage(dinfo);
            return true;
        }

        /// <summary>An area event's source: instigator, weapon and damage def. Two area hits in one tick from the same source on
        /// the same giant are one hit.</summary>
        public static long SourceKey(DamageInfo d)
        {
            unchecked
            {
                long k = d.Instigator?.thingIDNumber ?? -1;
                k = k * 1000003L + (d.Weapon?.shortHash ?? 0);
                return k * 1000003L + (d.Def?.shortHash ?? 0);
            }
        }

        public override void DeSpawn(DestroyMode mode = DestroyMode.Vanish)
        {
            Map m = Map;
            base.DeSpawn(mode);
            m?.GetComponent<MapComponent_HugeFootprints>()?.Notify_BlockerGone(this);
        }

        /// <summary>Ghost guard: a blocker the map component does not own (unclaimed cell, duplicate, stale save) removes
        /// itself.</summary>
        public override void TickRare()
        {
            base.TickRare();
            MapComponent_HugeFootprints mc = Map?.GetComponent<MapComponent_HugeFootprints>();
            if (mc == null || !mc.Owns(this) || !mc.IsClaimed(Position)) Destroy(DestroyMode.Vanish);
        }
    }
}
using System.Collections.Generic;
using RimWorld;
using UnityEngine;
using Verse;

namespace RimMandrake.HugeThings
{
    public class CompProperties_HugeFootprint : CompProperties
    {
        public CompProperties_HugeFootprint()
        {
            compClass = typeof(CompHugeFootprint);
        }
    }

    /// <summary>
    /// A huge plant's DESIRED footprint (ground-contact cells) and its selection rect, both from the picture the engine
    /// draws right now. Attached at startup to every plant def carrying RM_HugePlantExtension (HugeThingsStartup).
    ///
    /// It never spawns anything itself: it hands its desired cells to MapComponent_HugeFootprints, which owns the map-wide
    /// claim ledger, plans which cells may safely close, and keeps exactly one blocker per claimed cell. Holds no saved
    /// state; the map component rebuilds everything from the plants and the blockers on load.
    /// </summary>
    public class CompHugeFootprint : ThingComp
    {
        // Plant.Print's random draws for this cell (see RM_HugeFootprintKernel's header). Replayed on each use: the variant
        // index depends on the CURRENT graphic's sub-graphic count.
        private float jitterX, jitterZ;
        private bool flip;
        private int variantIndex;

        private readonly SignatureCache<CellRect> selectCache = new SignatureCache<CellRect>();
        private FootprintSignature lastTaken;
        private bool takenOnce;

        public RM_HugePlantExtension Ext => parent.def.GetModExtension<RM_HugePlantExtension>();

        public Plant Plant => parent as Plant;

        public int OwnerId => parent.thingIDNumber;

        /// <summary>Replays Plant.Print's Rand sequence for this cell: jitter, flipUv, Graphic_Random index. The global Rand
        /// state is always restored, even if a graphic getter throws (GPT review #16).</summary>
        private void Roll()
        {
            Plant p = Plant;
            if (p == null || !p.Spawned) return;
            Graphic g = p.Graphic;
            int n = g is Graphic_Random gr ? gr.SubGraphicsCount : 0;
            Rand.PushState();
            try
            {
                Rand.Seed = p.Position.GetHashCode();
                Vector3 j = Gen.RandomHorizontalVector(0.05f);
                bool f = Rand.Bool;
                int idx = n > 0 ? Rand.Range(0, n) : 0;
                jitterX = j.x;
                jitterZ = j.z;
                flip = f;
                variantIndex = idx;
            }
            finally
            {
                Rand.PopState();
            }
        }

        /// <summary>The measured variant of the picture actually drawn, or the union stand-in when the drawn texture was
        /// never measured (an immature or leafless graphic, an art override).</summary>
        private HugePlantVariant DrawnVariant(RM_HugePlantExtension ext, out bool measured, out int maskId, FootprintWorkBudget budget = null)
        {
            Graphic g = Plant.Graphic;
            if (g is Graphic_Random gr && gr.SubGraphicsCount > 0) g = gr.SubGraphicAtIndex(variantIndex);
            string path = g?.path;
            string name = path == null ? null : path.Substring(path.LastIndexOf('/') + 1);
            HugePlantVariant v = ext.Find(name, budget);
            budget?.Spend(ext.variants.Count);
            measured = v != null;
            maskId = measured ? ext.variants.IndexOf(v) + 1 : 0;
            return v ?? ext.GetUnion(budget);
        }

        /// <summary>Everything the footprint and the selection rect depend on right now.</summary>
        public FootprintSignature Signature(out HugeMask mask, FootprintWorkBudget budget = null)
        {
            Plant p = Plant;
            RM_HugePlantExtension ext = Ext;
            Roll();
            HugePlantVariant v = DrawnVariant(ext, out bool measured, out int maskId, budget);
            mask = ext.MaskFor(v, measured, budget);
            return new FootprintSignature
            {
                RootX = p.Position.x,
                RootZ = p.Position.z,
                MaskId = maskId,
                DrawX = p.def.graphicData?.drawSize.x ?? 1f,
                Visual = p.def.plant.visualSizeRange.LerpThroughRange(p.Growth),
                JitterX = jitterX,
                JitterZ = jitterZ,
                BlockScale = RM_HugeThingsSettings.plantTrunkScale,
                Flip = flip,
                Measured = measured,
                Blocking = RM_HugeThingsSettings.PlantTrunkActive && ext.blockingSupported,
                Selecting = RM_HugeThingsSettings.PlantSelectionActive,
                OldEnough = p.Growth >= ext.minGrowthToBlock,
            };
        }

        private static HugeQuad QuadOf(FootprintSignature s)
            => RM_HugeFootprintKernel.Quad(s.RootX, s.RootZ, s.DrawX, s.Visual, s.JitterX, s.JitterZ);

        /// <summary>Ground-contact cells wanted now, as cell keys (empty when blocking is off or the plant is too young).</summary>
        public List<long> DesiredKeys(FootprintWorkBudget budget = null)
        {
            Plant p = Plant;
            if (p == null || !p.Spawned || Ext == null) return new List<long>();
            FootprintSignature s = Signature(out HugeMask m, budget);
            return DesiredKeys(s, m, budget);
        }

        private static List<long> DesiredKeys(FootprintSignature s, HugeMask m, FootprintWorkBudget budget = null)
        {
            if (!s.Blocking || !s.OldEnough) return new List<long>();
            return RM_HugeFootprintKernel.ContactCells(s.RootX, s.RootZ, QuadOf(s), s.BlockScale, s.Flip, m, budget);
        }

        /// <summary>The cells this plant could EVER claim at full growth and the largest setting: the fixed planning window
        /// (Planner.Window) and the re-link scan, derived from the real transform (GPT review #7).</summary>
        public List<long> MaxKeys()
        {
            Plant p = Plant;
            RM_HugePlantExtension ext = Ext;
            FootprintSignature s = Signature(out HugeMask m);
            s.Visual = p.def.plant.visualSizeRange.max;
            s.BlockScale = RM_HugeThingsSettings.MaxTrunkScale;
            s.Blocking = true;
            s.OldEnough = true;
            HugeQuad q = QuadOf(s);
            List<long> keys = new List<long>();
            CellBox b = RM_HugeFootprintKernel.PictureBox(q, new HugeMask(), false);
            float bs = q.Size * s.BlockScale;
            int x0 = Mathf.FloorToInt(q.CentreX - bs / 2f), x1 = Mathf.CeilToInt(q.CentreX + bs / 2f);
            int z0 = Mathf.FloorToInt(q.MinZ), z1 = Mathf.CeilToInt(q.MinZ + bs);
            keys.Add(RM_HugeFootprintKernel.Key(System.Math.Min(b.MinX, x0), System.Math.Min(b.MinZ, z0)));
            keys.Add(RM_HugeFootprintKernel.Key(System.Math.Max(b.MaxX, x1), System.Math.Max(b.MaxZ, z1)));
            return keys;
        }

        /// <summary>The whole drawn picture plus every desired blocked cell; null when selection is off.</summary>
        public CellRect? SelectRect()
        {
            Plant p = Plant;
            if (p == null || Ext == null || !p.Spawned || !RM_HugeThingsSettings.PlantSelectionActive) return null;
            FootprintSignature sig = Signature(out HugeMask m);
            return selectCache.Get(sig, s =>
            {
                HugeQuad q = QuadOf(s);
                List<long> blocked = DesiredKeys(s, m);
                CellBox b = RM_HugeFootprintKernel.SelectBox(s.RootX, s.RootZ, RM_HugeFootprintKernel.PictureBox(q, m, s.Flip), blocked);
                return CellRect.FromLimits(b.MinX, b.MinZ, b.MaxX, b.MaxZ);
            });
        }

        /// <summary>True when the footprint may have changed since the map component last took it (growth, harvest,
        /// graphic, settings, position): GPT review #14.</summary>
        public bool Changed()
        {
            if (Plant == null || !Plant.Spawned || Ext == null) return false;
            FootprintSignature s = Signature(out _);
            return !takenOnce || !s.Equals(lastTaken);
        }

        /// <summary>HUGETHINGS_TRUNK_ZERO_BLOCKERS_1: what the footprint is computed from right now, for a bridge probe. Read-only
        /// (Roll replays the same deterministic draws).</summary>
        public string DebugDescribe()
        {
            Plant p = Plant;
            RM_HugePlantExtension ext = Ext;
            if (p == null || ext == null) return "plant=" + (p != null) + " ext=" + (ext != null);
            if (!p.Spawned) return "unspawned";
            FootprintSignature s = Signature(out HugeMask m);
            Graphic g = p.Graphic;
            if (g is Graphic_Random gr && gr.SubGraphicsCount > 0) g = gr.SubGraphicAtIndex(variantIndex);
            return "growth=" + p.Growth.ToString("0.###") + " graphic=" + (g?.path ?? "null") + " variant=" + variantIndex
                + " measured=" + s.Measured + " maskId=" + s.MaskId + " blocking=" + s.Blocking + " oldEnough=" + s.OldEnough
                + " minGrowth=" + ext.minGrowthToBlock + " blockingSupported=" + ext.blockingSupported + " visual=" + s.Visual.ToString("0.###")
                + " scale=" + s.BlockScale + " flip=" + s.Flip + " desired=" + DesiredKeys(s, m).Count + " takenOnce=" + takenOnce;
        }

        public void MarkTaken(FootprintSignature signature) { lastTaken = signature; takenOnce = true; }

        public void MarkTaken()
        {
            lastTaken = Signature(out _);
            takenOnce = true;
        }

        public override void PostSpawnSetup(bool respawningAfterLoad)
        {
            base.PostSpawnSetup(respawningAfterLoad);
            takenOnce = false;
            selectCache.Clear();
            parent.Map?.GetComponent<MapComponent_HugeFootprints>()?.Register(this);
        }

        public override void PostDeSpawn(Map map, DestroyMode mode = DestroyMode.Vanish)
        {
            base.PostDeSpawn(map, mode);
            map?.GetComponent<MapComponent_HugeFootprints>()?.Deregister(this);
            selectCache.Clear();
        }

        /// <summary>PLANT_FOOTPRINT_HARDENING_1 (A3.8): 1.6 Plant.TickInterval calls Plant.TickLong every 2000 ticks, and Plant.TickLong
        /// runs base.TickLong() (the comps) BEFORE it adds growth, so a CompTickLong check read last period's growth. The check
        /// runs from a Plant.TickLong postfix instead (HugeThingsCore). Harvest is caught by a PlantCollected postfix.</summary>
        public void Notify_PlantTickedLong()
        {
            // Queue cheaply; signature/geometry work belongs to the shared budgeted map scheduler.
            parent.Map?.GetComponent<MapComponent_HugeFootprints>()?.MarkDirty(this);
        }
    }
}
using System.Collections.Generic;
using System.Linq;
using HarmonyLib;
using RimWorld;
using UnityEngine;
using Verse;

namespace RimMandrake.HugeThings
{
    [DefOf]
    public static class HugeThingsDefOf
    {
        public static ThingDef RM_HugeTrunkBlocker;

        static HugeThingsDefOf()
        {
            DefOfHelper.EnsureInitializedInCtor(typeof(HugeThingsDefOf));
        }
    }

    /// <summary>
    /// The opt-in surface other mods call (the titan half of this mod does, for every race it tiers). Idempotent, and
    /// must run at startup - before any map loads - because vanilla files a Thing into the
    /// WithCustomRectForSelector lister group by its def's flag at the moment the Thing registers.
    /// </summary>
    public static class HugeThingsApi
    {
        public static void OptInPlant(ThingDef def, RM_HugePlantExtension ext = null)
        {
            if (def?.plant == null) return;
            if (def.GetModExtension<RM_HugePlantExtension>() == null)
            {
                if (def.modExtensions == null) def.modExtensions = new List<DefModExtension>();
                def.modExtensions.Add(ext ?? new RM_HugePlantExtension());
            }
            if (def.comps == null) def.comps = new List<CompProperties>();
            if (!def.comps.Any(c => c.compClass == typeof(CompHugeFootprint)))
            {
                def.comps.Add(new CompProperties_HugeFootprint());
            }
            def.hasCustomRectForSelector = true;
            ValidateRenderer(def);
        }

        /// <summary>
        /// The footprint replays vanilla Plant.Print's single-mesh branch (GPT review #7, #11). Anything else keeps the
        /// whole-quad selection but blocks nothing, with one error naming why: a multi-mesh plant, a thingClass that
        /// overrides Print, or a drawSize.x != 1 (the measurement frame assumes the quad's bottom is the root's south edge).
        /// </summary>
        public static void ValidateRenderer(ThingDef def)
        {
            RM_HugePlantExtension ext = def.GetModExtension<RM_HugePlantExtension>();
            if (ext == null) return;
            string why = null;
            if (def.plant.maxMeshCount != 1) why = "maxMeshCount " + def.plant.maxMeshCount + " (Plant.Print's multi-mesh branch)";
            else if (def.thingClass == null || !typeof(Plant).IsAssignableFrom(def.thingClass)) why = "thingClass is not a Plant";
            else if (AccessTools.Method(def.thingClass, "Print", new[] { typeof(SectionLayer) })?.DeclaringType != typeof(Plant))
                why = "thingClass " + def.thingClass.Name + " overrides Plant.Print";
            else if (ext.variants.Count > 0 && (def.graphicData?.drawSize.x ?? 1f) != 1f)
                why = "graphicData.drawSize.x " + def.graphicData.drawSize.x + " != 1";
            else if (ext.variants.Count > 0 && ext.measuredSize > 0f
                     && System.Math.Abs(ext.measuredSize - def.plant.visualSizeRange.max * (def.graphicData?.drawSize.x ?? 1f)) > 0.01f)
                why = "measuredSize " + ext.measuredSize + " != drawSize.x * visualMax (resized since measuring: rerun the tool)";
            if (why == null) why = Extensions_DataProblem(def, ext);   // A3.12: data the planner must never see
            ext.blockingSupported = why == null;
            if (why != null)
                Log.Error("[RimMandrake.HugeThings] " + def.defName + ": " + why + " -- it gets selection only, no ground footprint.");
            // Owner ruling 2026-10-07 21:08: art that touches the ground only in its own cell makes that cell solid. Verified
            // 1.6: PathGrid blocks a cell for ANY thing whose def is Impassable (not only edifices); cutting and harvesting use
            // PathEndMode.Touch (WorkGiver_PlantsCut, WorkGiver_GrowerHarvest, JobDriver_PlantWork), which reaches an
            // impassable 1x1 target from an adjacent open cell (TouchPathEndModeUtility.AddAllowedAdjacentRegions); a plant
            // never wipes anything on spawn (GenSpawn.SpawningWipes returns false for a Plant). Read at startup, so toggling
            // the footprint setting affects these plants after a restart.
            List<int> counts = new List<int>();
            foreach (HugePlantVariant v in ext.variants) counts.Add(v?.contact?.Count ?? 0);
            if (RootRule.RootImpassable(RM_HugeThingsSettings.PlantTrunkActive, ext.blockingSupported, counts))
            {
                def.passability = Traversability.Impassable;
                ext.rootImpassable = true;
            }
        }

        /// <summary>PLANT_FOOTPRINT_HARDENING_1 (A3.12): the extension's ConfigErrors, plus the def's own drawSize and visualSizeRange
        /// bounds, consulted at runtime: any problem turns blocking off for the def (selection only), so the planner never
        /// gets an unbounded window.</summary>
        private static string Extensions_DataProblem(ThingDef def, RM_HugePlantExtension ext)
        {
            foreach (string e in ext.ConfigErrors()) return e;
            float dx = def.graphicData?.drawSize.x ?? 1f;
            FloatRange vs = def.plant.visualSizeRange;
            if (!(dx > 0f && dx <= RM_HugePlantExtension.MaxDrawExtent)) return "graphicData.drawSize.x " + dx + " is not in (0, " + RM_HugePlantExtension.MaxDrawExtent + "]";
            if (!(vs.min > 0f && vs.max >= vs.min && vs.max * dx <= RM_HugePlantExtension.MaxDrawExtent))
                return "plant.visualSizeRange " + vs + " (x drawSize " + dx + ") is not a positive range within " + RM_HugePlantExtension.MaxDrawExtent;
            return null;
        }

        public static void OptInPawn(ThingDef def, RM_HugePawnExtension ext = null)
        {
            if (def?.race == null) return;
            if (def.GetModExtension<RM_HugePawnExtension>() == null)
            {
                if (def.modExtensions == null) def.modExtensions = new List<DefModExtension>();
                def.modExtensions.Add(ext ?? new RM_HugePawnExtension());
            }
            def.hasCustomRectForSelector = true;
        }

        /// <summary>The hitbox a huge pawn is clicked by right now, or null for "no bigger than vanilla".</summary>
        public static CellRect? PawnHitbox(Pawn pawn)
        {
            RM_HugePawnExtension ext = pawn?.def.GetModExtension<RM_HugePawnExtension>();
            if (ext == null || !pawn.Spawned || !RM_HugeThingsSettings.PawnHitboxActive) return null;
            Vector2 drawn = ActiveDrawSize(pawn);
            CellRect foot = pawn.OccupiedRect();   // Large Pawns' square when it is loaded, else one cell
            return FootprintMath.PawnHitbox(drawn.x, drawn.y, ext.hitboxFraction, RM_HugeThingsSettings.pawnHitboxScale, foot, pawn.DrawPos.ToIntVec3());
        }

        /// <summary>PLANT_INTERACTION_GUARDS_1 (C3.3): the drawSize of the graphic 1.6 PawnRenderNode_AnimalPart.GraphicFor actually
        /// draws (alternate graphic, else femaleGraphicData for a female, else bodyGraphicData), never smaller than the body's.</summary>
        public static Vector2 ActiveDrawSize(Pawn pawn)
        {
            PawnKindLifeStage stage = pawn.ageTracker?.CurKindLifeStage;
            Vector2 body = stage?.bodyGraphicData?.drawSize ?? Vector2.one;
            Vector2? active = null;
            try
            {
                if (stage?.bodyGraphicData != null && pawn.TryGetAlternate(out AlternateGraphic ag, out int _) && ag != null)
                    active = ag.GetGraphic(stage.bodyGraphicData.Graphic)?.drawSize;
                else if (pawn.gender == Gender.Female && stage?.femaleGraphicData != null)
                    active = stage.femaleGraphicData.drawSize;
            }
            catch (System.Exception e)
            {
                Log.ErrorOnce("[RimMandrake.HugeThings] could not resolve " + pawn + "'s drawn graphic; hitbox uses the body graphic: " + e,
                              pawn.def.shortHash ^ 0x4b17);
            }
            HitboxDraw.Pick(body.x, body.y, active.HasValue, active?.x ?? 0f, active?.y ?? 0f, out float x, out float y);
            return new Vector2(x, y);
        }

        public static CellRect Union(CellRect a, CellRect b) => FootprintMath.Union(a, b);
    }

    /// <summary>
    /// Clicking anywhere on a huge thing selects it. Vanilla already selects any Thing whose
    /// CustomRectForSelector contains the clicked cell (GenUI.ThingsUnderMouse) and draws the selection
    /// brackets around that rect (SelectionDrawer); Plant and Pawn simply never supply one. This postfix
    /// supplies it for opted-in defs only. Priority.Last so it widens, never narrows, Large Pawns' square.
    /// </summary>
    [HarmonyPatch(typeof(Thing), nameof(Thing.CustomRectForSelector), MethodType.Getter)]
    public static class Patch_Thing_CustomRectForSelector
    {
        [HarmonyPriority(Priority.Last)]
        public static void Postfix(Thing __instance, ref CellRect? __result)
        {
            if (!__instance.def.hasCustomRectForSelector) return;
            if (__instance is Plant plant)
            {
                CompHugeFootprint comp = plant.GetComp<CompHugeFootprint>();
                CellRect? r = comp?.SelectRect();
                if (r.HasValue) __result = __result.HasValue ? HugeThingsApi.Union(r.Value, __result.Value) : r;   // widen, never narrow
                return;
            }
            if (__instance is Pawn pawn)
            {
                CellRect? r = HugeThingsApi.PawnHitbox(pawn);
                if (r.HasValue) __result = __result.HasValue ? HugeThingsApi.Union(r.Value, __result.Value) : r;
            }
        }
    }

    /// <summary>PLANT_FOOTPRINT_HARDENING_1 (A3.8): the growth check runs after Plant.TickLong has added this period's growth.</summary>
    [HarmonyPatch(typeof(Plant), nameof(Plant.TickLong))]
    public static class Patch_Plant_TickLong
    {
        public static void Postfix(Plant __instance)
        {
            if (!__instance.def.hasCustomRectForSelector || !__instance.Spawned) return;
            __instance.GetComp<CompHugeFootprint>()?.Notify_PlantTickedLong();
        }
