            Reset(); map=Map(); var moved=Add(map,7,4,true);
            for(int tick=0;tick<10 && moved.Taken==0;tick++) Tick(tick,map);
            map.Component.Deregister(moved); map.Component.Register(moved);
            for(int tick=11;tick<30;tick++) Tick(tick,map);
