            Map map = Find.CurrentMap;
            if (map == null || parts.Length "'!= 2) return "FAIL expected pawn|blocker on current map";
            Pawn pawn = map.mapPawns.AllPawnsSpawned.FirstOrDefault(p => p.ThingID == parts[0]);
